graphql.query:
query HistoricoCompleto($pacienteId: ID) {
  historicoPaciente(pacienteId: $pacienteId) {
    pacienteId
    pacienteNome
    totalConsultas
    consultas {
      consultaId
      dataHora
      status
      observacoes
      medico { nome especialidade }
      eventos { tipo statusResultante versao ocorridoEm }
    }
  }
}

query Futuras($pacienteId: ID) {
  consultasFuturas(pacienteId: $pacienteId) { consultaId dataHora status }
}

query Filtrado($pacienteId: ID, $filtro: FiltroHistorico) {
  historicoPaciente(pacienteId: $pacienteId, filtro: $filtro) {
    totalConsultas
    consultas { consultaId status medico { especialidade } }
  }
}

query Estatisticas($pacienteId: ID) {
  estatisticasPaciente(pacienteId: $pacienteId) {
    pacienteId total agendadas realizadas canceladas futuras
  }
}

query Detalhe($consultaId: ID!) {
  consultaHistorico(consultaId: $consultaId) {
    consultaId status versao observacoes
    eventos { tipo statusResultante versao }
  }
}
